  @override
  Future<void> write(String name, String value) async {
    _validateName(name);
    // Preflight: with no default keychain (a broken/removed login keychain)
    // `add-generic-password` pops the system "Keychain Not Found" dialog
    // before failing — check quietly first so the caller degrades to
    // session-only without the prompt.
    final defaultKeychain = await _run('security', ['default-keychain']);
    if (defaultKeychain.exitCode != 0) {
      throw StateError(
        'no default keychain (exit ${defaultKeychain.exitCode})',
      );
    }
    final result = await _run('security', [
      'add-generic-password',
      '-s',
      secureKeyServiceName,
      '-a',
      name,
      '-w',
      value,
      '-U',
    ]);
    if (result.exitCode != 0) {
      // The stderr tail rides the diagnostic (gh-1679 review, same rule as
      // the read ladder's `_errorTail`): the live failure shapes — e.g.
      // `SecKeychainItemCreateFromContent (<default>): The authorization
      // was canceled by the user` (exit 154, the user canceling the
      // system keychain dialog) — live in the tail, and the caller's
      // missing-default-keychain remedy classification needs it.
      throw StateError(
        _errorTail(
          result,
          'security add-generic-password failed (exit ${result.exitCode})',
        ),
      );
    }
  }

  @override
  Future<void> delete(String name) async {
    _validateName(name);
    // A missing entry exits non-zero; deleting is idempotent by design.
    await _run('security', [
      'delete-generic-password',
      '-s',
      secureKeyServiceName,
      '-a',
      name,
    ]);
  }
}

