bool functionalKeychainRoundTrip(
 SecureKeyRunResult Function(List<String> args) runSecurity, {
 required String service,
 required String account,
 required String password,
}) {
 // Quiet preflight first: with no default keychain `add-generic-password`
 // pops the system "Keychain Not Found" dialog before failing — the same
 // order _MacosKeychainStore.write uses.
 if (runSecurity(const ['default-keychain']).exitCode != 0) return false;
 if (runSecurity([
   'add-generic-password',
   '-s', service,
   '-a', account,
   '-w', password,
   '-U',
 ]).exitCode != 0) {
   return false;
 }
 var wrote = false;
 var deleted = false;
 try {
   final find = runSecurity([
     'find-generic-password',
     '-s', service,
     '-a', account,
     '-w',
   ]);
   wrote = find.exitCode == 0 && _stripOneNewline(find.stdout) == password;
 } finally {
   // The throwaway probe item must not survive — even when the read-back
   // failed (a leftover secret in the developer keychain is exactly the
   // side effect this suite must not add).
   deleted = runSecurity([
     'delete-generic-password',
     '-s', service,
     '-a', account,
   ]).exitCode == 0;
 }
 // The full leg contract is write+read+delete: a failed delete means the
 // keychain state is not one the leg can rely on (and skipped is honest).
 return wrote && deleted;
}
